#include <stdio.h>

int binary_search(const int values[], int n, int target) {
    int left = 0;
    int right = n - 1;
    while (left <= right) {
        int mid = 0; /* TODO 1: replace 0 with the midpoint of the current closed interval */
        if (values[mid] == target) {
            return mid;
        }
        if (values[mid] < target) {
            left = mid; /* TODO 2: exclude the midpoint before searching the right half */
        } else {
            right = mid; /* TODO 3: exclude the midpoint before searching the left half */
        }
    }
    return 0; /* TODO 4: use the course's not-found return value */
}

int main(void) {
    int values[] = {3, 8, 14, 21, 29, 37, 45, 58};
    int n = (int)(sizeof(values) / sizeof(values[0]));
    int targets[] = {21, 3, 58, 20};
    for (int i = 0; i < 4; i++) {
        printf("target=%d index=%d\n", targets[i], binary_search(values, n, targets[i]));
    }
    return 0;
}
